// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;

    function setUp() public {
        c = new SimpleWallet();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether); // value must be > 0 to expose the bug; c is funded to cover it
        vm.deal(address(c), amount); // ensure the reference call succeeds
        vm.prank(address(this)); // setUp deployer is the owner
        c.sendMoney(address(rec), amount);
        assertTrue(rec.lastValue() == amount); // reference records exactly `amount`; mutant records 0
    }
}

contract Recorder {
    uint256 public lastValue;
    uint256 public calls;

    fallback() external payable {
        lastValue = msg.value;
        calls++;
    }
}
